/*
N2O PAPER
Version 1.0.3

A theme for Obsidian, by N2O Sync.
https://n2osync.com
*/

/* @settings

name: N2O Paper
id: n2o-paper
settings:
  -
    id: n2o-looks
    title: Looks
    type: heading
    level: 1
  -
    id: n2o-palette
    title: Palette
    description: One hue runs through the whole theme, the sidebar, headings, tapes, table headers, links and the tinted scraps. Each palette moves all of it together.
    type: class-select
    allowEmpty: false
    default: n2o-palette-forest
    options:
      - n2o-palette-forest
      - n2o-palette-ink
      - n2o-palette-oxblood
      - n2o-palette-graphite
      - n2o-palette-sepia
      - n2o-palette-rose
      - n2o-palette-coal
  -
    id: n2o-right
    title: Right sidebar
    description: The right sidebar can stand a step apart from the left, deeper in the palette's own colour, or in another material, walnut wood or brushed dark metal.
    type: class-select
    allowEmpty: false
    default: n2o-right-palette
    options:
      - n2o-right-palette
      - n2o-right-deeper
      - n2o-right-walnut
      - n2o-right-metal
  -
    id: n2o-no-black-frame
    title: No black frame
    description: The spine down the left edge and the bar across the top of the window are black bookcloth by default, the palette's hue deep in the black, the spine keeping its weave and its sewn seam. Turn this on to give them the palette's colour instead.
    type: class-toggle
  -
    id: n2o-heading-scale
    title: Heading size
    description: Scales every heading level together. Medium is the theme's own.
    type: class-select
    allowEmpty: false
    default: n2o-headings-medium
    options:
      - n2o-headings-medium
      - n2o-headings-large
      - n2o-headings-small
  -
    id: n2o-font-type
    title: Font set
    description: Five faces ship with the theme. Any note can override this on its own with a cssclasses property.
    type: class-select
    allowEmpty: false
    default: n2o-font-default
    options:
      - n2o-font-default
      - n2o-font-inter
      - n2o-font-ibm
      - n2o-font-fira
      - n2o-font-iawriter-quattro
  -
    id: n2o-code-theme
    title: Code blocks
    description: Warm dark is the theme's own. Paper matches the page instead. Each sets every syntax colour together.
    type: class-select
    allowEmpty: false
    default: n2o-code-warm-dark
    options:
      - n2o-code-warm-dark
      - n2o-code-light
      - n2o-code-contrast
  -
    id: n2o-code-font
    title: Code font
    description: Fira Code ships with the theme, so it looks the same on every machine. Quattro is duospace, for notes that are more prose than program.
    type: class-select
    allowEmpty: false
    default: n2o-code-font-fira
    options:
      - n2o-code-font-fira
      - n2o-code-font-system
      - n2o-code-font-quattro
      - n2o-code-font-body
  -
    id: n2o-ui-font
    title: Interface font
    description: The sidebars and their panes. Inter is the theme's own; Serif matches the page. The text field under Typography still overrides the rest of the chrome.
    type: class-select
    allowEmpty: false
    default: n2o-ui-font-inter
    options:
      - n2o-ui-font-inter
      - n2o-ui-font-serif
      - n2o-ui-font-ibm
      - n2o-ui-font-quattro
      - n2o-ui-font-system
  -
    id: n2o-code-text
    title: Code text size
    description: Moves the type size and the space around it together, so small code stays readable.
    type: class-select
    allowEmpty: false
    default: n2o-code-text-medium
    options:
      - n2o-code-text-medium
      - n2o-code-text-large
      - n2o-code-text-small
  -
    id: n2o-everything
    title: All settings
    type: heading
    level: 1
  -
    id: n2o-colours
    title: Colours
    type: heading
    level: 2
  -
    id: background-primary
    title: Editor background
    type: variable-themed-color
    format: hex
    default-light: '#ede8dc'
    default-dark: '#191919'
  -
    id: text-normal
    title: Body text
    type: variable-themed-color
    format: hex
    default-light: '#2b2a26'
    default-dark: '#d4d4d4'
  -
    id: text-muted
    title: Muted text
    type: variable-themed-color
    format: hex
    default-light: '#5d5c55'
    default-dark: '#9b9b98'
  -
    id: text-faint
    title: Faint text
    type: variable-themed-color
    format: hex
    default-light: '#9a978c'
    default-dark: '#7f7f7d'
  -
    id: bold-color
    title: Bold text
    type: variable-themed-color
    format: hex
    default-light: '#2b2a26'
    default-dark: '#ff5c95'
  -
    id: italic-color
    title: Italic text
    type: variable-themed-color
    format: hex
    default-light: '#2e5a45'
    default-dark: '#4fc9d8'
  -
    id: link-color
    title: Links
    type: variable-themed-color
    format: hex
    default-light: '#2e5a45'
    default-dark: '#e070d8'
  -
    id: link-color-hover
    title: Links, hovered
    type: variable-themed-color
    format: hex
    default-light: '#22392d'
    default-dark: '#f29ceb'
  -
    id: link-external-color
    title: External links
    type: variable-themed-color
    format: hex
    default-light: '#2e5a45'
    default-dark: '#4aa8c4'
  -
    id: text-selection
    title: Text selection
    type: variable-themed-color
    format: hex
    default-light: 'rgba(185, 190, 169, 0.55)'
    default-dark: '#31463d'
  -
    id: text-highlight-bg
    title: Highlight
    type: variable-themed-color
    format: hex
    default-light: 'rgba(107, 122, 98, 0.32)'
    default-dark: '#5b4b00'
  -
    id: divider-color
    title: Dividers and borders
    type: variable-themed-color
    format: hex
    default-light: '#cdc7b6'
    default-dark: '#2f2f2f'
  -
    id: n2o-typography
    title: Typography
    type: heading
    level: 2
  -
    id: line-height-normal
    title: Line height
    type: variable-number-slider
    default: 1.6
    min: 1.1
    max: 2.2
    step: 0.05
  -
    id: font-paragraph
    title: Body paragraph size
    description: The size of body text.
    type: variable-number
    default: 1.125
    format: rem
  -
    id: bold-weight
    title: Bold weight
    type: variable-number-slider
    default: 600
    min: 500
    max: 900
    step: 50
  -
    id: n2o-headings-plain
    title: Plain headings
    description: Every heading level takes its own colour from the palette by default. Turn this on to set them all in one colour.
    type: class-toggle
  -
    id: n2o-layout
    title: Layout
    type: heading
    level: 2
  -
    id: width-body-content
    title: Width of body content
    description: Where you write and read.
    type: variable-number
    default: 700
    format: px
  -
    id: n2o-desk-margin
    title: Desk margin
    description: The desk showing either side of the sheet. The gap above and below stays put. Most visible with readable line width off.
    type: variable-number-slider
    default: 96
    min: 8
    max: 160
    step: 4
    format: px
  -
    id: radius-s
    title: Small corner radius
    type: variable-number
    default: 4
    format: px
  -
    id: radius-m
    title: Medium corner radius
    type: variable-number
    default: 8
    format: px
  -
    id: radius-l
    title: Large corner radius
    type: variable-number
    default: 10
    format: px
  -
    id: n2o-small-pinned-tabs
    title: Small pinned tabs
    description: Pinned tabs get smaller
    type: class-toggle
  -
    id: n2o-hide-ribbon
    title: Hide ribbon
    description: Hides the icons in the left ribbon.
    type: class-toggle
  -
    id: n2o-new-note-button-top
    title: New note button at the top
    description: The new note button sits at the bottom of the sidebar by default. Turn this on to leave it where Obsidian puts it.
    type: class-toggle
  -
    id: n2o-paper
    title: Paper
    type: heading
    level: 2
  -
    id: n2o-paper-texture
    title: Paper texture
    description: How much of the paper shows through, all four layers together. 50 is the theme's own.
    type: variable-number-slider
    default: 50
    min: 0
    max: 100
    step: 5
  -
    id: n2o-paper-light
    title: Light across the page
    description: Brighter at the top left, dimmer at the bottom right, darker at the very edge. 0 is flat, 200 is twice the theme's own.
    type: variable-number-slider
    default: 100
    min: 0
    max: 200
    step: 10
  -
    id: n2o-paper-drift
    title: Drift of tone
    description: The slow warm-and-cool drift across every paper. 100 is the theme's own, 0 is none.
    type: variable-number-slider
    default: 100
    min: 0
    max: 100
    step: 5
  -
    id: n2o-quiet-callouts
    title: Quiet callouts
    description: Every callout on cream with a moss tape from the palette, the type still named on it. For notes with many callouts, where thirteen colours would be too many. Off by default.
    type: class-toggle
  -
    id: n2o-callout-cards
    title: Card callouts
    description: A coloured band across the top with the title in it, paper below, and only the bottom edge torn. Off by default, which is the taped scrap.
    type: class-toggle
  -
    id: n2o-marker-spots
    title: Marker-filled spot tapes
    description: Danger and Bug tapes hatched in like a marker, with an ink outline. Off by default, plain tape in the two colours.
    type: class-toggle
  -
    id: n2o-aged-photos
    title: Aged photos
    description: Every photo as an old print, faded warm, with dust, fine scratches, a crease and worn pale edges. Off by default. One photo can be aged on its own with the aged flag, as in ![[photo.png|aged]].
    type: class-toggle
  -
    id: n2o-flat-paper
    title: Flat paper
    description: Every texture and the ink layer off at once.
    type: class-toggle
  -
    id: n2o-coil-binding
    title: Coil binding
    description: A steel coil down the left edge of the sheet, through a column of punched holes. Off by default.
    type: class-toggle
  -
    id: n2o-coil-pitch
    title: Coil spacing
    description: The distance between turns of the coil. Closer turns make a finer coil, further apart a coarser one. 40 is the theme's own.
    type: variable-number-slider
    default: 40
    min: 24
    max: 64
    step: 4
    format: px
  -
    id: n2o-coil-slant
    title: Coil slant
    description: How steeply the turns of the coil lean, from flat rings to a steep spiral. Sets the sheet's coil and the coil on quotes.
    type: class-select
    allowEmpty: false
    default: n2o-coil-slant-regular
    options:
      - n2o-coil-slant-flat
      - n2o-coil-slant-gentle
      - n2o-coil-slant-regular
      - n2o-coil-slant-steep
  -
    id: n2o-quote-no-coil
    title: No coil on quotes
    description: A steel coil down the left edge of every quote in reading mode, a size finer than the sheet's, is on by default. Turn this on to remove it.
    type: class-toggle
  -
    id: n2o-components
    title: Components
    type: heading
    level: 2
  -
    id: callout-padding
    title: Callout padding
    description: A CSS shorthand, so all four sides can differ. Example: 16px 12px 12px 24px
    type: variable-text
    default: 32px 36px 26px 40px
  -
    id: callout-title-size
    title: Callout title size
    type: variable-number
    default: 1
    format: em
  -
    id: callout-blend-mode
    title: Callout blend mode
    description: How a callout's tint mixes with the page behind it.
    type: variable-select
    default: normal
    options:
      - normal
      - darken
      - lighten
      - multiply
      - screen
  -
    id: n2o-plain-checkboxes
    title: Plain checkboxes
    description: Checkboxes are drawn in pencil by default. Turn this on for Obsidian's plain ones, for example if you style them in your own snippet.
    type: class-toggle
  -
    id: n2o-checkbox-size
    title: Checkbox size
    type: variable-number
    default: 22
    format: px
  -
    id: n2o-checkbox-radius
    title: Checkbox corner radius
    description: Plain checkboxes only. A pencil box is drawn by hand and has no corners to round.
    type: variable-number
    default: 4
    format: px
  -
    id: n2o-checkbox-color
    title: Checkbox colour
    description: The pencil line of an open box and the ink of a done one. Left alone, open boxes are graphite and done ones follow the palette.
    type: variable-color
    format: hex
    default: '#3b3833'
  -
    id: tag-background
    title: Tag background
    type: variable-themed-color
    format: hex
    default-light: '#d6d9c6'
    default-dark: '#3a2f27'
  -
    id: tag-color
    title: Tag text
    type: variable-themed-color
    format: hex
    default-light: '#4a5c50'
    default-dark: '#f68d45'
  -
    id: tag-radius
    title: Tag corner radius
    type: variable-number
    default: 2
    format: em
  -
    id: tag-size
    title: Tag size
    type: variable-number
    default: 0.72
    format: em
  -
    id: tag-border-width
    title: Tag border width
    type: variable-number
    default: 0
    format: px
  -
    id: table-cell-fontsize
    title: Table cell size
    description: Font size of table cell
    type: variable-number
    default: 1
    format: rem
  -
    id: table-head-fontsize
    title: Table head size
    description: Font size of table head cell
    type: variable-number
    default: 0.95
    format: rem
  -
    id: blockquote-size
    title: Quote text size
    type: variable-number
    default: 1
    format: rem
  -
    id: blockquote-font-style
    title: Quote text style
    type: variable-select
    default: italic
    options:
      - italic
      - normal
  -
    id: n2o-table-style
    title: Table style
    description: Card is a pale piece laid on the sheet with an accent header band. Ledger is the open form, green capitals on a green rule and hairlines, no card. Rows keeps the card and stripes every second row instead of every second column.
    type: class-select
    allowEmpty: false
    default: n2o-table-card
    options:
      - n2o-table-card
      - n2o-table-ledger
      - n2o-table-rows
  -
    id: n2o-code
    title: Code
    type: heading
    level: 2
  -
    id: n2o-code-plain-as-code
    title: Style plain fences as code
    description: A fence with no language is set as paper by default, closer to a note than a terminal. Turn this on to make it look like every other code block. Reading mode only.
    type: class-toggle
  -
    id: code-background
    title: Block background
    description: One colour for both light and dark, because a code block is dark in both.
    type: variable-color
    format: hex
    default: '#23221f'
  -
    id: code-border-color
    title: Block border
    type: variable-color
    format: hex
    default: '#34322e'
  -
    id: code-radius
    title: Corner radius
    type: variable-number
    default: 4
    format: px
  -
    id: n2o-code-line-numbers
    title: Line numbers
    description: Numbers in the margin of a code block, in the editor. Reading mode hands a block to one element, where a counter has nothing to count. Off by default.
    type: class-toggle
  -
    id: n2o-toggles
    title: Interface toggles
    type: heading
    level: 2
  -
    id: n2o-hide-scrollbar
    title: Hide scrollbars
    description: Scrollbars are visible by default. Turn this on to hide them.
    type: class-toggle
  -
    id: n2o-hide-icons
    title: Hide icons in the sidebar
    description: File and folder icons are on by default. Turn this on to remove them.
    type: class-toggle
  -
    id: n2o-accent-frame
    title: Accent frame around the window
    description: A two pixel line of the theme colour along the window's edge. Off by default.
    type: class-toggle
  -
    id: n2o-flat
    title: Flat page
    description: Rules are scored into the paper and headings are pressed into it by default. Turn this on for a flat page with plain lines and plain type.
    type: class-toggle
  -
    id: n2o-advanced
    title: Advanced
    type: heading
    level: 1
  -
    id: n2o-advanced-headings
    title: Headings, one level at a time
    type: heading
    level: 2
  -
    id: size-h1
    title: H1 size
    description: Font size of H1
    type: variable-number
    default: 2.4
    format: rem
  -
    id: size-h2
    title: H2 size
    description: Font size of H2
    type: variable-number
    default: 1.85
    format: rem
  -
    id: size-h3
    title: H3 size
    description: Font size of H3
    type: variable-number
    default: 1.5
    format: rem
  -
    id: size-h4
    title: H4 size
    description: Font size of H4
    type: variable-number
    default: 1.25
    format: rem
  -
    id: size-h5
    title: H5 size
    description: Font size of H5
    type: variable-number
    default: 1.1
    format: rem
  -
    id: size-h6
    title: H6 size
    description: Font size of H6
    type: variable-number
    default: 1
    format: rem
  -
    id: h1-weight
    title: H1 weight
    type: variable-number-slider
    default: 400
    min: 300
    max: 900
    step: 50
  -
    id: h2-weight
    title: H2 weight
    type: variable-number-slider
    default: 400
    min: 300
    max: 900
    step: 50
  -
    id: h3-weight
    title: H3 weight
    type: variable-number-slider
    default: 400
    min: 300
    max: 900
    step: 50
  -
    id: h4-weight
    title: H4 weight
    type: variable-number-slider
    default: 400
    min: 300
    max: 900
    step: 50
  -
    id: h5-weight
    title: H5 weight
    type: variable-number-slider
    default: 400
    min: 300
    max: 900
    step: 50
  -
    id: h6-weight
    title: H6 weight
    type: variable-number-slider
    default: 400
    min: 300
    max: 900
    step: 50
  -
    id: h1-color
    title: H1 colour
    type: variable-themed-color
    format: hex
    default-light: '#2e5a45'
    default-dark: '#4ec3d0'
  -
    id: h2-color
    title: H2 colour
    type: variable-themed-color
    format: hex
    default-light: '#2e5a45'
    default-dark: '#5fd39c'
  -
    id: h3-color
    title: H3 colour
    type: variable-themed-color
    format: hex
    default-light: '#2e5a45'
    default-dark: '#ff6b76'
  -
    id: h4-color
    title: H4 colour
    type: variable-themed-color
    format: hex
    default-light: '#2e5a45'
    default-dark: '#3fc0c0'
  -
    id: h5-color
    title: H5 colour
    type: variable-themed-color
    format: hex
    default-light: '#4a5c50'
    default-dark: '#e0a0a0'
  -
    id: h6-color
    title: H6 colour
    type: variable-themed-color
    format: hex
    default-light: '#7c8279'
    default-dark: '#b39a8b'
  -
    id: n2o-advanced-code
    title: Code, colour by colour
    type: heading
    level: 2
  -
    id: code-normal
    title: Block text
    type: variable-color
    format: hex
    default: '#e8e4dc'
  -
    id: code-normal-inline
    title: Inline code text
    description: Inline code keeps the paper surface, so this is the red-on-paper colour rather than the block one.
    type: variable-color
    format: hex
    default: '#2e5a45'
  -
    id: code-comment
    title: Comments
    type: variable-color
    format: hex
    default: '#85807a'
  -
    id: code-keyword
    title: Keywords
    type: variable-color
    format: hex
    default: '#ff7ab2'
  -
    id: code-string
    title: Strings
    type: variable-color
    format: hex
    default: '#9ece6a'
  -
    id: code-function
    title: Functions
    description: In Live Preview this also colours properties, builtins and attributes, because Obsidian maps them all to this one variable there.
    type: variable-color
    format: hex
    default: '#7aa2f7'
  -
    id: code-property
    title: Properties
    description: Reading mode only. Live Preview colours properties from Functions above, which is Obsidian's own mapping.
    type: variable-color
    format: hex
    default: '#7dcfff'
  -
    id: code-value
    title: Values and numbers
    type: variable-color
    format: hex
    default: '#e0af68'
  -
    id: code-operator
    title: Operators
    type: variable-color
    format: hex
    default: '#bb9af7'
  -
    id: code-punctuation
    title: Punctuation
    type: variable-color
    format: hex
    default: '#9aa0a6'
  -
    id: code-tag
    title: Tags and selectors
    type: variable-color
    format: hex
    default: '#f7768e'
  -
    id: code-important
    title: Important and constants
    type: variable-color
    format: hex
    default: '#ff9e64'
  -
    id: code-size
    title: Code size
    type: variable-number
    default: 0.875
    format: em
  -
    id: n2o-advanced-fonts
    title: Font stacks
    type: heading
    level: 2
  -
    id: n2o-font-set
    title: Custom body family
    description: Any font on your machine, as a CSS font stack. Overrides the set above. A note that sets its own font still wins over this.
    type: variable-text
    default: Georgia, Iowan Old Style, Palatino Linotype, Book Antiqua, serif
  -
    id: font-interface-theme
    title: Interface font
    description: Sidebar, menus, settings and every other chrome surface.
    type: variable-text
    default: Georgia, serif
  -
    id: font-monospace-theme
    title: Monospace font
    description: Code blocks and inline code.
    type: variable-text
    default: Menlo, SFMono-Regular, Consolas, monospace
  -
    id: n2o-advanced-paper
    title: Paper, piece by piece
    type: heading
    level: 2
  -
    id: n2o-paper-no-fibres
    title: No fibres
    description: The sparse fibres in the sheet are on by default. Turn this on to remove them.
    type: class-toggle
  -
    id: n2o-paper-no-tooth
    title: No tooth
    description: The fine grain of the stock, on the sheet and the scraps, is on by default. Turn this on to remove it.
    type: class-toggle
  -
    id: n2o-paper-no-creases
    title: No creases
    description: The faint creases in the sheet are on by default. Turn this on to remove them.
    type: class-toggle
  -
    id: n2o-softbox
    title: Softbox
    description: A soft light over the page, like a photographer's softbox. A pool of light on the desk, the head of the sheet brighter, every scrap, quote and table card lit from above, and wide soft shadows that lift them off the page. Text stays crisp. 0 is off, 140 is the theme's own.
    type: variable-number-slider
    default: 140
    min: 0
    max: 280
    step: 10
  -
    id: n2o-softbox-panels
    title: Softbox on the sidebars
    description: The same soft light, very gently, on the two sidebar panels, a glow at the top of each where it meets the page. 0 is off, 100 is the theme's own, 200 is twice it.
    type: variable-number-slider
    default: 100
    min: 0
    max: 200
    step: 10
