  --font-family-ibm: "IBMRegular", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --font-family-iawriter-quattro: "iaWriterQuattro", mono;
  --font-family-fira: "Fira Code", "Courier New", Courier, monospace;

  /* --font-family-serif: Inter, Helvetica, Arial, sans-serif; */
  --font-family-sans: var(--font-family-inter);
  /* --font-family-serif: Times, Georgia, "Times New Roman", serif; */

  --font-default: var(--font-family-sans);
  

  --table-cell-fontsize: 1rem;
