/* Font sets.
 *
 * Each set declares --n2o-font-set; one rule below applies it. Because the
 * variable inherits, the same mechanism covers both scopes: the plugin puts
 * the class on body for the whole vault, and a note puts it on its own view
 * through `cssclasses`, which is where Obsidian actually lands it. */
/* The interface font: one variable the sidebar rules read, set by the
 * Interface font picker. Inter is the default and needs no class. */
body:where(.theme-light) { --n2o-ui-font: var(--font-family-inter); }
body:where(.theme-light).n2o-ui-font-serif   { --n2o-ui-font: var(--font-family-serif); }
body:where(.theme-light).n2o-ui-font-ibm     { --n2o-ui-font: var(--font-family-ibm); }
body:where(.theme-light).n2o-ui-font-quattro { --n2o-ui-font: var(--font-family-iawriter-quattro); }
body:where(.theme-light).n2o-ui-font-system  { --n2o-ui-font: system-ui, "Segoe UI", Helvetica, Arial, sans-serif; }

/* the default lives on body at the lowest specificity, so any option
 * class on body outranks it */
body:where(.theme-light) { --n2o-font-set: var(--font-family-serif); }
:where(body.theme-light).n2o-font-inter            { --n2o-font-set: var(--font-family-inter); }
:where(body.theme-light).n2o-font-ibm              { --n2o-font-set: var(--font-family-ibm); }
:where(body.theme-light).n2o-font-fira             { --n2o-font-set: var(--font-family-fira); }
:where(body.theme-light).n2o-font-iawriter-quattro {
  --n2o-font-set: var(--font-family-iawriter-quattro);
  /* Quattro is drawn wide and needs pulling in to sit with the rest. */
  --n2o-font-tracking: -0.03rem;
}

/* The same sets again, for a class that is NOT on body.
 *
 * A note picks its own face with a `cssclasses` property, and Obsidian puts
 * those classes on the VIEW, not on body: .markdown-source-view and
 * .markdown-preview-view. The block above only ever matched body, so the
 * per-note font, and the plugin command that writes it, changed nothing on
 * screen. These rules carry more specificity than the body ones, which is
 * what a note overriding the vault-wide choice should do. */
body.theme-light .n2o-font-default            { --n2o-font-set: var(--font-family-serif); }
body.theme-light .n2o-font-inter              { --n2o-font-set: var(--font-family-inter); }
body.theme-light .n2o-font-ibm                { --n2o-font-set: var(--font-family-ibm); }
body.theme-light .n2o-font-fira               { --n2o-font-set: var(--font-family-fira); }
body.theme-light .n2o-font-iawriter-quattro {
  --n2o-font-set: var(--font-family-iawriter-quattro);
  --n2o-font-tracking: -0.03rem;
}

:where(.theme-light) .markdown-source-view,
:where(.theme-light) .markdown-preview-view {
  font-family: var(--n2o-font-set, var(--font-family-sans));
  letter-spacing: var(--n2o-font-tracking, normal);
}


